    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The recursive Eilenberg–Mac Lane operator", H("The recursive Eilenberg–Mac Lane operator"), Blocks(
        Paragraph(Text("All degrees are natural numbers. Pure DerivedOp constructions are integer combinations of pairs of simplex maps; a realization uses any abelian C : Type u with Category.{v} C, independent universes, and any bisimplicial X. Composition MTwo.comp MOne means first apply MOne and then MTwo.")),
        Paragraph(Text("The endomorphism hOp(q) sums over every split p+(q-p)=q and every shuffle of that split. Its realization is alexanderWhitney followed by shuffleMap. The degree-raising family phiOp is defined recursively: phiOp(0)=0 and phiOp(q+1)=-(phiOp(q)).prime+(hOp(q+1)).prime.comp(D0op(q+1)). The negative sign belongs to this recursion.")),
        Paragraph(Text("The representable bisimplicial free abelian object detects every formal coefficient: evaluating an operator on its universal diagonal generator is injective. This detects the operator-level chain identities from their realized versions. The raw degree-raising family is zero except from i to i+1; the normalized homotopy is obtained later by Moore inclusion and retraction, after the structural norm error has been killed.")),
        Describe.Lean(DescribeId.Create("ez-recursiveoperators-hletter-318a62"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.hLetter"), H("hLetter"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("A single summand of `h = ∇f`: split `q = p + (q - p)`, apply the AW front/back faces, then apply one `(p, q-p)` shuffle. The two `eqToHom`s transport across `p + (q-p) = q`.")), Paragraph(Text("In this notation, noncomputable def hLetter (q : ℕ) (p : Fin (q + 1)) (μ : Shuffle (p : ℕ) (q - p)) : OpLetter q q."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-recursiveoperators-hop-3d200f"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.hOp"), H("hOp"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`h = ∇f` as a derived operator: sum over the Alexander-Whitney split and then over shuffles.")), Paragraph(Text("In this notation, noncomputable def hOp (q : ℕ) : DerivedOp q q."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-recursiveoperators-hletter-realize-50dfcd"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.hLetter_realize"), H("hLetter_realize"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Realization of one `hLetter` summand is the corresponding `awComponent ≫ ezComponent` shuffle summand. This identifies the AW front/back faces with the shuffle degeneracies.")), Paragraph(Text("In this notation, lemma hLetter_realize (X : BisimplicialObject C) (q : ℕ) (p : Fin (q + 1)) (μ : Shuffle (p : ℕ) (q - p)) : (hLetter q p μ).realizeLetter X = eqToHom (by simp [Nat.add_sub_cancel' (Nat.lt_succ_iff.mp p.isLt)]) ≫ awComponent X p (q - p) ≫ ((X.obj (Opposite.op ⦋(p : ℕ)⦌)).map (shuffleSndHom μ).op ≫ (X.map (shuffleFstHom μ).op).app (Opposite.op ⦋(p : ℕ) + (q - p)⦌)) ≫ eqToHom (by simp [Nat.add_sub_cancel' (Nat.lt_succ_iff.mp p.isLt)])."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-recursiveoperators-realize-hop-a82bd9"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.realize_hOp"), H("realize_hOp"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`hOp` realizes to the composite `alexanderWhitney ≫ shuffleMap = ∇f` on `FTwo.obj X`.")), Paragraph(Text("In this notation, lemma realize_hOp (X : BisimplicialObject C) (q : ℕ) : (hOp q).realize X = (alexanderWhitney X ≫ shuffleMap X).f q."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-recursiveoperators-phiop-bfbb45"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.phiOp"), H("phiOp"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("**The Eilenberg–Mac Lane homotopy `Φ`** as a derived operator, defined by EM's recursion (2.13): `Φ₀ = 0` and `Φ_{q} = − Φ'_{q-1} + h'_{q} D₀` for `q > 0`. Here `Φ_q : (K×L)_q → (K×L)_{q+1}`.")), Paragraph(Text("In this notation, noncomputable def phiOp : (q : ℕ) → DerivedOp q (q + 1)."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-recursiveoperators-phihomraw-3d7acb"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.phiHomRaw"), H("phiHomRaw"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`Φ` packaged as a degree-`+1` `Homotopy.hom` family on `FTwo.obj X` (the unnormalized diagonal): `phiOp i` realized (transported along `j = i+1`) on the single nonzero entry, `0` elsewhere.")), Paragraph(Text("In this notation, noncomputable def phiHomRaw (X : BisimplicialObject C) (i j : ℕ) : (FTwo.obj X).X i ⟶ (FTwo.obj X).X j."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-recursiveoperators-prevd-phihomraw-03ee7e"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.prevD_phiHomRaw"), H("prevD_phiHomRaw"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`prevD` of `phiHomRaw` is the realized operator `∂Φ` (apply `Φ` then `∂`): `prevD n (phiHomRaw X) = (phiOp n).realize X ≫ (boundaryOp n).realize X`.")), Paragraph(Text("In this notation, lemma prevD_phiHomRaw (X : BisimplicialObject C) (n : ℕ) : prevD n (phiHomRaw X) = DerivedOp.realize X ((boundaryOp n).comp (phiOp n))."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-recursiveoperators-dnext-phihomraw-87e7fc"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.dNext_phiHomRaw"), H("dNext_phiHomRaw"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`dNext` of `phiHomRaw` (at `n+1`) is the realized operator `Φ∂` (apply `∂` then `Φ`): `dNext (n+1) (phiHomRaw X) = (boundaryOp n).realize X ≫ (phiOp n).realize X`.")), Paragraph(Text("In this notation, lemma dNext_phiHomRaw (X : BisimplicialObject C) (n : ℕ) : dNext (n + 1) (phiHomRaw X) = DerivedOp.realize X ((phiOp n).comp (boundaryOp n))."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-recursiveoperators-idop-5bd6c9"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.idOp"), H("idOp"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("The identity operator `i = 𝟙 × 𝟙 : (K×L)_q → (K×L)_q` (EM's `i`). Realizes to `𝟙` (`realize_single_id`).")), Paragraph(Text("In this notation, noncomputable def idOp (q : ℕ) : DerivedOp q q."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-recursiveoperators-ysimp-896229"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.ysimp"), H("ysimp"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("The represented simplicial type `Δ[s] : b ↦ (⦋b⦌ ⟶ ⦋s⦌)` (the `SimplexCategory` Yoneda).")), Paragraph(Text("In this notation, abbrev ysimp (s : ℕ) : SimplexCategoryᵒᵖ ⥤ Type."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-recursiveoperators-bitype-4d255a"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.bitype"), H("bitype"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("The bi-represented **bisimplicial type** at `(s, s)`: `(a, b) ↦ (⦋a⦌ ⟶ ⦋s⦌) × (⦋b⦌ ⟶ ⦋s⦌)`, the horizontal map acting on the first factor and the vertical on the second.")), Paragraph(Text("In this notation, def bitype (s : ℕ) : BisimplicialObject (Type)."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-recursiveoperators-freewhisker-a735dc"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.freeWhisker"), H("freeWhisker"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Postcompose a (bi)simplicial type with the free `ℤ`-module functor.")), Paragraph(Text("In this notation, noncomputable def freeWhisker : (SimplexCategoryᵒᵖ ⥤ Type) ⥤ (SimplexCategoryᵒᵖ ⥤ ModuleCat.{0} ℤ)."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-recursiveoperators-univop-c1aa86"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.univOp"), H("univOp"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("A **universal bisimplicial object** detecting all derived operators out of degree `s`: the free `ℤ`-module on the bi-represented bisimplicial set at `(s, s)`. Realizing a derived operator against it recovers it as a `Finsupp`, so `realize (univOp s)` is injective (`realize_univOp_injective`).")), Paragraph(Text("In this notation, noncomputable def univOp (s : ℕ) : BisimplicialObject (ModuleCat.{0} ℤ)."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-recursiveoperators-realize-univop-injective-a2a961"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.realize_univOp_injective"), H("realize_univOp_injective"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`realize` against the universal object is **injective**: a derived operator is determined by its realization on `univOp`. This is the faithfulness principle that lets us deduce formal `DerivedOp` identities from their (realized) chain-level counterparts.")), Paragraph(Text("In this notation, lemma realize_univOp_injective {s q : ℕ} : Function.Injective (fun M : DerivedOp s q => M.realize (univOp s))."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-recursiveoperators-boundaryop-comp-hop-e74fab"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.boundaryOp_comp_hOp"), H("boundaryOp_comp_hOp"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("**`∂ h = h ∂` (EM line 155, `∂*h' = h'∂*`).** `h = ∇f` is a chain map, so `boundaryOp` commutes with `hOp`. Proof: `realize` against the universal object is injective, and on the realized side this is just the chain-map condition `comm` of `alexanderWhitney ≫ shuffleMap`.")), Paragraph(Text("In this notation, lemma boundaryOp_comp_hOp (q : ℕ) : (boundaryOp q).comp (hOp (q + 1)) = (hOp q).comp (boundaryOp q)."))), DescribeRole.Theorem),
