        Describe.Lean(DescribeId.Create("ez-recursiveoperators-hop-zero-comp-retraction-ab7731"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.hOp_zero_comp_retraction"), H("hOp_zero_comp_retraction"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Base degree: `hOp 0` agrees with the identity after postcomposing with `retractionNTwo`.")), Paragraph(Text("In this notation, lemma hOp_zero_comp_retraction (X : BisimplicialObject C) : DerivedOp.realize X (hOp 0) ≫ (retractionNTwo X).f 0 = DerivedOp.realize X (idOp 0) ≫ (retractionNTwo X).f 0."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-recursiveoperators-derivedop-comp-neg-c6a1fa"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.comp_neg"), H("DerivedOp.comp_neg"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Negation in the operator applied first negates the composite.")), Paragraph(Text("In this notation, lemma DerivedOp.comp_neg {s q r : ℕ} (MTwo : DerivedOp q r) (N : DerivedOp s q) : MTwo.comp (-N) = -(MTwo.comp N)."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-recursiveoperators-derivedop-neg-comp-8052c7"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/RecursiveOperators.neg_comp"), H("DerivedOp.neg_comp"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Negation in the operator applied second negates the composite.")), Paragraph(Text("In this notation, lemma DerivedOp.neg_comp {s q r : ℕ} (M : DerivedOp q r) (K : DerivedOp s q) : (-M).comp K = -(M.comp K)."))), DescribeRole.Theorem),
